function demoMain(idx,label){
  var exprs=["2 + 3 * 4","(10 - 2) / 4","7 * (3 + 1)","100 / (5 * 2)"];
  var e=exprs[idx%exprs.length];
  function tok(s){return s.match(/\d+|[+\-*/()]/g);}
  function parse(t){var p=0;
    function expr(){var v=term();while(p<t.length&&(t[p]=='+'||t[p]=='-')){var o=t[p++];var r=term();v=o=='+'?v+r:v-r;}return v;}
    function term(){var v=fact();while(p<t.length&&(t[p]=='*'||t[p]=='/')){var o=t[p++];var r=fact();v=o=='*'?v*r:Math.floor(v/r);}return v;}
    function fact(){var x=t[p++];if(x=='('){var v=expr();p++;return v;}return parseInt(x,10);}
    return expr();}
  var code="PUSH ops for '"+e+"' -> [EVAL]"; var val=parse(tok(e));
  return "["+label+"] compiled '"+e+"' to stack-machine code ("+code+") => result "+val;
}

